update markets set ui = jsonb_set(ui, '{copy}', '{"logo_sub": "THAILAND", "hero_sub_en": "Moderated listings · owner-direct rooms · BTS/MRT search. Built for Myanmar and other communities in Thailand, in your language.", "search_ph_en": "Search area or BTS/MRT station… e.g. On Nut", "safety_en": "Safety first: never transfer money before viewing the room in person.", "ph_station": "On Nut", "ph_area": "Bang Na", "ph_title": "Furnished room, 5 min to On Nut BTS", "ph_title_wanted": "Working lady looking for a room near Mo Chit", "ph_phone": "+66 8x xxx xxxx", "hero_sub_my": "သေချာစစ်ဆေးထားသည့် ကြော်ငြာများ · အိမ်ရှင်တိုက်ရိုက် ငှားရန်အခန်းများ · BTS/MRT ဖြင့် ရှာနိုင်မှု။ ထိုင်းရောက် မြန်မာအပါအဝင် အခြားအသိုင်းအဝိုင်းများအတွက် မိမိတို့ ဘာသာစကားဖြင့် လွယ်ကူစွာ ရှာနိုင်အောင် ဖန်တီးထားပါသည်။", "search_ph_my": "နေရာ သို့မဟုတ် BTS/MRT ဘူတာ ရိုက်ရှာပါ... e.g. On Nut", "safety_my": "ဘေးကင်းရေး အဓိကပါ - အခန်းကို ကိုယ်တိုင် မကြည့်ရသေးဘဲ ပိုက်ဆံ ကြိုမလွှဲပါနဲ့။"}'::jsonb) where id = 'th';
update markets set ui = jsonb_set(ui, '{copy}', '{"logo_sub": "MYANMAR", "hero_sub_en": "Moderated listings · owner-direct rooms. Built for our community in Myanmar, in your language.", "search_ph_en": "Search township or area… e.g. Sanchaung", "safety_en": "Safety first: never transfer money before viewing the room in person.", "ph_station": "", "ph_area": "Sanchaung", "ph_title": "Room for rent in Sanchaung, near Hledan", "ph_title_wanted": "Student looking for a room near Hledan", "ph_phone": "+95 9 xxx xxx xxx", "hero_sub_my": "စိစစ်ပြီး ကြော်ငြာများ · အိမ်ရှင်တိုက်ရိုက် အခန်းများ။ မြန်မာအသိုင်းအဝိုင်းအတွက် ကိုယ့်ဘာသာစကားဖြင့် သီးသန့် ပြုလုပ်ထားပါသည်။", "search_ph_my": "မြို့နယ် သို့မဟုတ် နေရာ ရှာရန်… e.g. Sanchaung", "safety_my": "လုံခြုံရေးအတွက် - အခန်းကို လူကိုယ်တိုင် မကြည့်ရသေးဘဲ ငွေကြိုမလွှဲပါနဲ့။"}'::jsonb) where id = 'mm';
